// Normaliza nombres a formato "Juan Perez Osorio" (sin importar si vienen en mayúscula/minúscula/mezclado)
function formatoNombre(s) {
  if (!s) return s;
  const minus = new Set([
    "de",
    "del",
    "la",
    "las",
    "los",
    "y",
    "da",
    "do",
    "dos",
    "e",
    "di",
    "van",
    "von",
  ]);
  return String(s)
    .trim()
    .replace(/\s+/g, " ")
    .toLowerCase()
    .split(" ")
    .map((w, i) =>
      i > 0 && minus.has(w) ? w : w.charAt(0).toUpperCase() + w.slice(1)
    )
    .join(" ");
}

