// Icono genérico de archivo PDF (hoja roja con esquina doblada)
function IconoPdf({ size = 26 }) {
  return (
    <svg width={size} height={Math.round(size * 1.18)} viewBox="0 0 24 28" aria-hidden="true" style={{ display: "block", flexShrink: 0 }}>
      <path d="M3 1.5h11.5L21 8v16.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-21a2 2 0 0 1 0-2z" fill="#d8352a" />
      <path d="M14.5 1.5V6a2 2 0 0 0 2 2H21z" fill="#a8241b" />
      <text x="12" y="20" textAnchor="middle" fontSize="7.2" fontWeight="800" fontFamily="Arial, Helvetica, sans-serif" fill="#fff" letterSpacing="0.2">PDF</text>
    </svg>
  );
}

// Icono de ojo (línea fina) — reemplaza al emoji 👁/🙈 en toda la app
function IconoOjo({ size = 16, off = false, style }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0, verticalAlign: "-0.15em", display: "inline-block", ...style }} aria-hidden="true">
      <path d="M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z" />
      <circle cx="12" cy="12" r="3" />
      {off && <path d="M4 4l16 16" />}
    </svg>
  );
}

