function Card({ children, style = {}, hover = false, onClick }) {
  const [h, setH] = useState(false);
  return (
    <div
      onClick={onClick}
      onMouseEnter={() => hover && setH(true)}
      onMouseLeave={() => setH(false)}
      style={{
        background: "rgba(255,255,255,0.95)",
        borderRadius: 20,
        border: "1px solid rgba(60,60,67,0.10)",
        padding: "18px 20px",
        boxShadow: h
          ? "0 12px 36px rgba(0,0,0,0.14), 0 3px 10px rgba(0,0,0,0.07)"
          : "0 1px 4px rgba(0,0,0,0.06), 0 4px 16px rgba(0,0,0,0.05)",
        transition: "all 0.22s cubic-bezier(0.25,0.46,0.45,0.94)",
        transform: h && onClick ? "translateY(-1px)" : "none",
        cursor: onClick ? "pointer" : "default",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        ...style,
      }}
    >
      {children}
    </div>
  );
}

function Btn({
  children,
  onClick,
  style = {},
  variant = "primary",
  disabled = false,
}) {
  const [h, setH] = useState(false);
  const [pressed, setPressed] = useState(false);
  const base =
    variant === "primary"
      ? {
          background:
            h && !disabled
              ? `linear-gradient(135deg, ${C.primaryDark} 0%, #1a2d4a 100%)`
              : `linear-gradient(135deg, ${C.primary} 0%, #0f3d6e 100%)`,
          color: "white",
          opacity: disabled ? 0.5 : 1,
          boxShadow:
            h && !disabled
              ? `0 6px 20px ${C.primary}55`
              : `0 2px 8px ${C.primary}33`,
        }
      : variant === "ghost"
      ? {
          background: h ? "rgba(0,0,0,0.06)" : "rgba(0,0,0,0.03)",
          color: C.gray,
          border: `1px solid rgba(60,60,67,0.18)`,
          boxShadow: "none",
        }
      : {
          background: h ? "rgba(0,0,0,0.08)" : "rgba(0,0,0,0.05)",
          color: C.dark,
          boxShadow: "none",
        };
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      onMouseEnter={() => setH(true)}
      onMouseLeave={() => {
        setH(false);
        setPressed(false);
      }}
      onMouseDown={() => setPressed(true)}
      onMouseUp={() => setPressed(false)}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        padding: "10px 20px",
        borderRadius: 14,
        border: variant === "ghost" ? `1px solid rgba(60,60,67,0.18)` : "none",
        cursor: disabled ? "not-allowed" : "pointer",
        fontSize: 14,
        fontWeight: 600,
        letterSpacing: "-0.018em",
        transform: pressed && !disabled ? "scale(0.97)" : "scale(1)",
        transition: "all 0.16s cubic-bezier(0.25,0.46,0.45,0.94)",
        WebkitTapHighlightColor: "transparent",
        ...base,
        ...style,
      }}
    >
      {children}
    </button>
  );
}

