function PartiturasEnsayo({ docs }) {
  const grupos = {};
  (docs || []).forEach((d) => {
    const k = cantoBaseEnsayo(d);
    if (!k) return;
    (grupos[k] = grupos[k] || []).push(d);
  });
  const cantos = Object.keys(grupos).sort((a, b) => a.localeCompare(b));

  if (cantos.length === 0) {
    return (
      <div
        style={{
          background: "rgba(242,242,247,0.7)",
          borderRadius: 16,
          padding: "32px 22px",
          textAlign: "center",
          color: "#8a8a90",
          fontSize: 13.5,
          lineHeight: 1.6,
        }}
      >
        🎼 Aún no hay cantos cargados.
        <br />
        El encargado los sube desde{" "}
        <strong>menú → Subir Material</strong> (partitura, pistas por
        voz y la ficha del canto).
      </div>
    );
  }

  return (
    <div>
      {cantos.map((nombre) => (
        <CantoHub key={nombre} nombre={nombre} rows={grupos[nombre]} />
      ))}
    </div>
  );
}

function parseDriveFolderId(s) {
  if (!s) return "";
  const m = s.match(/folders\/([a-zA-Z0-9_-]+)/);
  if (m) return m[1];
  const m2 = s.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (m2) return m2[1];
  return s.trim();
}
const VOCES_KEYS_DRIVE = [
  "soprano",
  "contralto",
  "alto",
  "mezzo",
  "tenor",
  "bajo",
  "bass",
  "baritono",
  "barítono",
  "instrumental",
  "instrumentos",
  "solista",
];
function vozDeNombre(n) {
  const t = (n || "").toLowerCase();
  return VOCES_KEYS_DRIVE.find((v) => t.includes(v)) || null;
}
function normalizaVoz(v) {
  if (!v) return "Todas";
  if (v === "bass") return "Bajo";
  if (v === "alto" || v === "mezzo") return "Contralto";
  if (v === "instrumentos") return "Instrumental";
  return v.charAt(0).toUpperCase() + v.slice(1);
}
function limpiaCantoNombre(n) {
  return (n || "").replace(/^\s*\d+\s*[.\-)]?\s*/, "").trim();
}

function ImportadorDrive({ onDone }) {
  const [apiKey, setApiKey] = useState("");
  const [folder, setFolder] = useState(
    "https://drive.google.com/drive/folders/1aaNiiV5ruZ2SFfnpWRpr5SBdXq3U6biz"
  );
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [importing, setImporting] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    (async () => {
      try {
        const k = await getConfig("drive_api_key");
        if (k) setApiKey(k);
      } catch (e) {}
    })();
  }, []);

  async function listChildren(folderId) {
    let files = [],
      pageToken = "";
    do {
      const q = encodeURIComponent(
        `'${folderId}' in parents and trashed=false`
      );
      const url = `https://www.googleapis.com/drive/v3/files?q=${q}&key=${apiKey}&fields=nextPageToken,files(id,name,mimeType,shortcutDetails(targetId,targetMimeType))&pageSize=1000&supportsAllDrives=true&includeItemsFromAllDrives=true${
        pageToken ? `&pageToken=${pageToken}` : ""
      }`;
      const r = await fetch(url);
      if (!r.ok)
        throw new Error(
          `No se pudo leer la carpeta (código ${r.status}). Revisa la clave y que la carpeta sea accesible por enlace.`
        );
      const d = await r.json();
      files = files.concat(d.files || []);
      pageToken = d.nextPageToken || "";
    } while (pageToken);
    return files;
  }

  async function walk(folderId, parentName, grandName, acc, depth, stats) {
    if (depth > 7) return;
    const children = await listChildren(folderId);
    for (const c of children) {
      let mime = c.mimeType,
        id = c.id;
      const name = c.name;
      if (
        mime === "application/vnd.google-apps.shortcut" &&
        c.shortcutDetails
      ) {
        mime = c.shortcutDetails.targetMimeType || mime;
        id = c.shortcutDetails.targetId || id;
      }
      if (mime === "application/vnd.google-apps.folder") {
        stats.folders++;
        await walk(id, name, parentName, acc, depth + 1, stats);
      } else {
        stats.files++;
        acc.push({ file: { id, name, mimeType: mime }, parentName, grandName });
      }
    }
  }

  function clasificar(e) {
    const name = e.file.name || "";
    const low = name.toLowerCase();
    const mime = e.file.mimeType || "";
    const voz = vozDeNombre(e.parentName);
    const canto = limpiaCantoNombre(voz ? e.grandName : e.parentName);
    let categoria;
    if (mime === "application/pdf" || low.endsWith(".pdf"))
      categoria = /letra|texto|acorde/.test(low) ? "Letras" : "Partituras";
    else if (mime.startsWith("audio/") || /\.(mp3|m4a|wav|ogg|aac)$/.test(low))
      categoria = "Audio";
    else if (mime.startsWith("video/") || /\.(mp4|mov|webm)$/.test(low))
      categoria = "Video";
    else return null;
    return {
      canto: canto || "Sin nombre",
      cuerda_mat: normalizaVoz(voz),
      categoria,
      nombre: name,
      url: `https://drive.google.com/file/d/${e.file.id}/preview`,
      drive_id: e.file.id,
      audiencia: "coro",
    };
  }

  async function explorar() {
    setMsg("");
    setItems([]);
    const id = parseDriveFolderId(folder);
    if (!apiKey) {
      setMsg("Pega primero tu clave de Google API.");
      return;
    }
    if (!id) {
      setMsg("Pega el enlace de la carpeta de Drive.");
      return;
    }
    setLoading(true);
    try {
      try {
        await setConfig("drive_api_key", apiKey);
      } catch (e) {}
      const acc = [];
      const stats = { folders: 0, files: 0 };
      await walk(id, "", "", acc, 0, stats);
      const clasif = acc.map(clasificar).filter(Boolean);
      setItems(clasif);
      if (clasif.length)
        setMsg(
          `Encontré ${clasif.length} archivo(s) en ${
            new Set(clasif.map((i) => i.canto)).size
          } canto(s). Revisa y luego Importar.`
        );
      else if (stats.files > 0)
        setMsg(
          `Recorrí ${stats.folders} carpeta(s) y vi ${stats.files} archivo(s), pero ninguno parece audio/partitura (deben ser .mp3/.m4a/.wav o .pdf).`
        );
      else if (stats.folders > 0)
        setMsg(
          `Recorrí ${stats.folders} carpeta(s) pero sin archivos dentro (o son accesos directos que no pude abrir).`
        );
      else
        setMsg(
          "La carpeta no devolvió contenido. Verifica el enlace, la clave y que esté en “Cualquiera con el enlace”."
        );
    } catch (e) {
      setMsg("⚠️ " + e.message);
    }
    setLoading(false);
  }

  async function importar() {
    if (!items.length) return;
    setImporting(true);
    let ok = 0;
    for (let i = 0; i < items.length; i++) {
      try {
        await supabase("repertorio_drive", { method: "POST", body: items[i] });
        ok++;
      } catch (e) {}
      setMsg(`Importando ${i + 1}/${items.length}…`);
    }
    setMsg(`✓ Listo: ${ok}/${items.length} importados.`);
    setItems([]);
    if (onDone) onDone();
    setImporting(false);
  }

  const inp = {
    width: "100%",
    padding: "10px 12px",
    borderRadius: 10,
    border: "1px solid rgba(60,60,67,0.2)",
    fontSize: 13,
    marginBottom: 8,
    boxSizing: "border-box",
  };
  return (
    <div
      style={{
        background: "#f5f9ff",
        border: "1px solid #cfe0fb",
        borderRadius: 14,
        padding: 16,
        marginBottom: 18,
      }}
    >
      <div
        style={{
          fontSize: 13,
          fontWeight: 800,
          color: "#0a5ac8",
          marginBottom: 10,
        }}
      >
        📥 Importar desde Google Drive
      </div>
      <input
        value={apiKey}
        onChange={(e) => setApiKey(e.target.value)}
        placeholder="Clave de Google API (AIza…)"
        style={inp}
      />
      <input
        value={folder}
        onChange={(e) => setFolder(e.target.value)}
        placeholder="Enlace de la carpeta de Drive"
        style={inp}
      />
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <button
          onClick={explorar}
          disabled={loading}
          style={{
            background: "#0a5ac8",
            color: "white",
            border: "none",
            borderRadius: 10,
            padding: "9px 15px",
            fontSize: 12.5,
            fontWeight: 700,
            cursor: "pointer",
          }}
        >
          {loading ? "Explorando…" : "Explorar carpeta"}
        </button>
        {items.length > 0 && (
          <button
            onClick={importar}
            disabled={importing}
            style={{
              background: "#15803d",
              color: "white",
              border: "none",
              borderRadius: 10,
              padding: "9px 15px",
              fontSize: 12.5,
              fontWeight: 700,
              cursor: "pointer",
            }}
          >
            {importing ? "Importando…" : `Importar ${items.length}`}
          </button>
        )}
      </div>
      {msg && (
        <div
          style={{
            fontSize: 12,
            color: msg.startsWith("⚠️") ? "#b91c1c" : "#3a3a40",
            marginTop: 10,
            lineHeight: 1.5,
          }}
        >
          {msg}
        </div>
      )}
    </div>
  );
}

