function CuotaRecordatorioWidget({ members, user, setSection, onReload }) {
  const [data, setData] = useState(null);
  const [inscribiendo, setInscribiendo] = useState(false);
  const [cuotaInfo, setCuotaInfo] = useState("");
  const [modalTipo, setModalTipo] = useState(false);
  const [modalConfirmado, setModalConfirmado] = useState(null); // { esEstudiante } — post-inscripción

  async function fetchCuotaData() {
    try {
      const [cuotas, pagos, mc] = await Promise.all([
        finDbGet("fin_cuotas").catch(() => []),
        finDbGet("fin_pagos").catch(() => []),
        finDbGet("fin_miembros_cuotas").catch(() => []),
      ]);
      setData({ cuotas: cuotas || [], pagos: pagos || [], mc: mc || [] });
    } catch {
      setData({ cuotas: [], pagos: [], mc: [] });
    }
  }
  useEffect(() => {
    fetchCuotaData();
    getConfig("cuota_info")
      .then((v) => {
        if (v) setCuotaInfo(v);
      })
      .catch(() => {});
  }, []);

  async function inscribirmeCuota(esEstudiante) {
    if (!user?.id || inscribiendo) return;
    setModalTipo(false);
    setInscribiendo(true);
    try {
      await finDbPost("fin_miembros_cuotas", {
        integrante_id: user.id,
        es_estudiante: esEstudiante,
      });
      await fetchCuotaData();
      if (onReload) onReload();
      setModalConfirmado({ esEstudiante });
    } catch (e) {
      alert("No se pudo inscribir: " + (e?.message || ""));
    }
    setInscribiendo(false);
  }

  const [bajaOpen, setBajaOpen] = useState(false);
  const [motivoBaja, setMotivoBaja] = useState("");
  const [dandoBaja, setDandoBaja] = useState(false);
  async function darmeDeBaja() {
    if (!motivoBaja || dandoBaja) return;
    const row = (data?.mc || []).find((m) => m.integrante_id === user?.id);
    if (!row) {
      setBajaOpen(false);
      return;
    }
    setDandoBaja(true);
    try {
      await finDbDelete("fin_miembros_cuotas", row.id);
      setBajaOpen(false);
      setMotivoBaja("");
      await fetchCuotaData();
      if (onReload) onReload();
    } catch (e) {
      alert("No se pudo dar de baja: " + (e?.message || ""));
    }
    setDandoBaja(false);
  }

  if (!data) return null;

  const inscritosIds = new Set((data.mc || []).map((m) => m.integrante_id));
  const yoInscrito = inscritosIds.has(user?.id);
  const esGestorCuota = esCuerdaAdmin(user) || esCuerdaContador(user);

  // Quien no participa en la cuota ve una invitación para inscribirse
  if (!yoInscrito && !esGestorCuota) {
    return (
      <div
        style={{
          background: "linear-gradient(180deg,#f5f9ff,#eaf2ff)",
          border: "1px solid #cfe0fb",
          borderRadius: 18,
          padding: "16px 18px",
          marginBottom: 16,
          display: "flex",
          alignItems: "center",
          gap: 15,
          flexWrap: "wrap",
        }}
      >
        <div
          style={{
            width: 46,
            height: 46,
            borderRadius: 14,
            flexShrink: 0,
            background: "rgba(10,90,200,0.10)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 22,
          }}
        >
          💸
        </div>
        <div style={{ flex: 1, minWidth: 220 }}>
          <div
            style={{
              fontSize: 10,
              fontWeight: 800,
              color: "#0a5ac8",
              letterSpacing: "0.07em",
              textTransform: "uppercase",
              marginBottom: 2,
            }}
          >
            Cuota mensual del coro
          </div>
          <div
            style={{
              fontSize: 14,
              fontWeight: 700,
              color: "#0b2a52",
              lineHeight: 1.35,
            }}
          >
            ¿Quieres participar en el pago de la cuota mensual?
          </div>
          <div
            style={{
              fontSize: 12,
              color: "#3a5a80",
              lineHeight: 1.5,
              marginTop: 5,
            }}
          >
            {cuotaInfo ||
              "La cuota mensual es un aporte voluntario con el que reunimos fondos para nuestras actividades extraprogramáticas: salidas, convivencias y celebraciones que nos permiten compartir y fortalecer los lazos del coro más allá de los ensayos y las misas."}
          </div>
          <div style={{ fontSize: 11.5, color: "#6a8ab0", marginTop: 5 }}>
            Al inscribirte tendrás acceso a la información de gastos del coro.
          </div>
        </div>
        <button
          onClick={() => setModalTipo(true)}
          disabled={inscribiendo}
          style={{
            flexShrink: 0,
            background: "#0a5ac8",
            border: "none",
            borderRadius: 11,
            padding: "10px 17px",
            fontSize: 12.5,
            fontWeight: 700,
            color: "white",
            cursor: inscribiendo ? "default" : "pointer",
            opacity: inscribiendo ? 0.7 : 1,
          }}
        >
          {inscribiendo ? "Inscribiendo…" : "Quiero participar →"}
        </button>
      </div>
    );
  }

  if (!finMesVigente()) return null;
  const mes = finCurrentMesIso();
  const inscritos = (members || []).filter((m) => inscritosIds.has(m.id));
  if (inscritos.length === 0) return null;

  const pagaron = new Set(
    (data.pagos || [])
      .filter((p) => p.mes === mes && (p.tipo === "cuota" || !p.tipo))
      .map((p) => p.integrante_id)
  );
  const pendientes = inscritos.filter((m) => !pagaron.has(m.id));
  const alDia = pendientes.length === 0;
  if (alDia && !yoInscrito) return null; // gestor no inscrito y todos al día → nada que mostrar

  const total = inscritos.length;
  const pagados = total - pendientes.length;
  const pct = total ? Math.round((pagados / total) * 100) : 0;
  const cuotaMes = (data.cuotas || []).find((c) => c.mes === mes);
  const valor = cuotaMes?.valor;
  const yoPague = pagaron.has(user?.id);
  const esGestor = esCuerdaAdmin(user) || esCuerdaContador(user);

  return (
    <div
      style={{
        background: "linear-gradient(180deg,#f5f9ff,#eaf2ff)",
        border: "1px solid #cfe0fb",
        borderRadius: 18,
        padding: "16px 18px",
        marginBottom: 16,
        display: "flex",
        alignItems: "center",
        gap: 15,
        flexWrap: "wrap",
      }}
    >
      <div
        style={{
          width: 46,
          height: 46,
          borderRadius: 14,
          flexShrink: 0,
          background: "rgba(10,90,200,0.10)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {yoPague ? (
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#0a5ac8"
            strokeWidth="2.6"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M20 6 9 17l-5-5" />
          </svg>
        ) : (
          <span style={{ fontSize: 21, fontWeight: 800, color: "#0a5ac8" }}>
            $
          </span>
        )}
      </div>
      <div style={{ flex: 1, minWidth: 220 }}>
        <div
          style={{
            fontSize: 10,
            fontWeight: 800,
            color: "#0a5ac8",
            letterSpacing: "0.07em",
            textTransform: "uppercase",
            marginBottom: 2,
          }}
        >
          Cuota del coro · {finMesLabel(mes)}
        </div>
        <div
          style={{
            fontSize: 15,
            fontWeight: 800,
            color: "#0b2a52",
            letterSpacing: "-0.01em",
            lineHeight: 1.3,
          }}
        >
          {alDia
            ? `¡Todos al día con la cuota de ${finMesLabel(mes)}! 🎉`
            : yoPague
            ? `Estás al día. Aún faltan ${pendientes.length} ${
                pendientes.length === 1 ? "integrante" : "integrantes"
              } por pagar.`
            : `Tienes tu cuota de ${finMesLabel(mes)} pendiente${
                valor ? ` — ${finFmtCLP(valor)}` : ""
              }. ¡Ponte al día!`}
        </div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            marginTop: 9,
          }}
        >
          <div
            style={{
              flex: 1,
              maxWidth: 240,
              height: 7,
              borderRadius: 6,
              background: "rgba(10,90,200,0.14)",
              overflow: "hidden",
            }}
          >
            <div
              style={{
                width: `${pct}%`,
                height: "100%",
                borderRadius: 6,
                background: "linear-gradient(90deg,#3b82f6,#0a5ac8)",
              }}
            />
          </div>
          <span style={{ fontSize: 11.5, fontWeight: 700, color: "#0a5ac8" }}>
            {pagados}/{total} al día
          </span>
        </div>
        {yoInscrito && !yoPague && (
          <div
            style={{
              marginTop: 10,
              background: "#fff7ed",
              border: "1px solid #fed7aa",
              borderRadius: 10,
              padding: "10px 13px",
              fontSize: 12,
              color: "#7c2d12",
              lineHeight: 1.65,
            }}
          >
            💸 <strong>Tienes el pago pendiente.</strong> Realiza tu
            transferencia y envía el{" "}
            <strong>comprobante por el WhatsApp del grupo</strong> para que la
            contadora lo registre en el sistema.
          </div>
        )}
      </div>
      {yoInscrito && !bajaOpen && (
        <button
          onClick={() => setBajaOpen(true)}
          style={{
            flexShrink: 0,
            background: "white",
            border: "1px solid #e3b3b0",
            color: "#c0392b",
            fontSize: 12,
            fontWeight: 700,
            cursor: "pointer",
            borderRadius: 10,
            padding: "8px 14px",
          }}
        >
          Darme de baja
        </button>
      )}
      {esGestor && (
        <button
          onClick={() => setSection("finanzas")}
          style={{
            flexShrink: 0,
            background: "#0a5ac8",
            border: "none",
            borderRadius: 11,
            padding: "9px 16px",
            fontSize: 12.5,
            fontWeight: 700,
            color: "white",
            cursor: "pointer",
          }}
        >
          Gestionar cuotas →
        </button>
      )}
      {yoInscrito && bajaOpen && (
        <div
          style={{
            flexBasis: "100%",
            borderTop: "1px solid rgba(10,90,200,0.15)",
            marginTop: 4,
            paddingTop: 10,
            display: "flex",
            flexWrap: "wrap",
            alignItems: "center",
            gap: 8,
          }}
        >
          <span style={{ fontSize: 12, color: "#0b2a52", fontWeight: 600 }}>
            Motivo de la baja:
          </span>
          <select
            value={motivoBaja}
            onChange={(e) => setMotivoBaja(e.target.value)}
            style={{
              fontSize: 12.5,
              padding: "7px 10px",
              borderRadius: 9,
              border: "1px solid #cfe0fb",
              background: "white",
              color: "#1c1c1e",
            }}
          >
            <option value="">Selecciona un motivo…</option>
            <option value="Motivos económicos">Motivos económicos</option>
            <option value="Pausa temporal">Pausa temporal</option>
            <option value="Me retiro del coro">Me retiro del coro</option>
            <option value="Ya no deseo participar">
              Ya no deseo participar
            </option>
            <option value="Otro">Otro</option>
          </select>
          <button
            onClick={darmeDeBaja}
            disabled={!motivoBaja || dandoBaja}
            style={{
              background: !motivoBaja ? "#cbd5e1" : "#c0392b",
              border: "none",
              borderRadius: 9,
              padding: "7px 13px",
              fontSize: 12,
              fontWeight: 700,
              color: "white",
              cursor: !motivoBaja || dandoBaja ? "default" : "pointer",
            }}
          >
            {dandoBaja ? "Procesando…" : "Confirmar baja"}
          </button>
          <button
            onClick={() => {
              setBajaOpen(false);
              setMotivoBaja("");
            }}
            style={{
              background: "none",
              border: "none",
              color: "#8a8a90",
              fontSize: 12,
              cursor: "pointer",
            }}
          >
            Cancelar
          </button>
        </div>
      )}

      {/* ── Modal: instrucciones de pago post-inscripción ── */}
      {modalConfirmado && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.45)",
            backdropFilter: "blur(4px)",
            WebkitBackdropFilter: "blur(4px)",
            zIndex: 9999,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              background: "rgba(255,255,255,0.97)",
              borderRadius: 22,
              padding: "28px 24px",
              maxWidth: 380,
              width: "90%",
              boxShadow: "0 24px 72px rgba(0,0,0,0.18)",
            }}
          >
            <div
              style={{ fontSize: 34, textAlign: "center", marginBottom: 10 }}
            >
              ✅
            </div>
            <div
              style={{
                fontSize: 16,
                fontWeight: 700,
                color: "#1c1c1e",
                textAlign: "center",
                marginBottom: 6,
              }}
            >
              ¡Te inscribiste correctamente!
            </div>
            <div
              style={{
                fontSize: 13,
                color: "#3a3a40",
                textAlign: "center",
                marginBottom: 18,
                lineHeight: 1.6,
              }}
            >
              Quedaste inscrito como{" "}
              <strong>
                {modalConfirmado.esEstudiante
                  ? "Estudiante · $3.000"
                  : "Adulto"}
              </strong>
              .
            </div>

            {/* Instrucciones de pago */}
            <div
              style={{
                background: "#fff7ed",
                border: "1px solid #fed7aa",
                borderRadius: 14,
                padding: "14px 16px",
                marginBottom: 18,
              }}
            >
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 700,
                  color: "#7c2d12",
                  marginBottom: 8,
                  display: "flex",
                  alignItems: "center",
                  gap: 6,
                }}
              >
                💸 Debes pagar la cuota de este mes
              </div>
              <div
                style={{ fontSize: 12.5, color: "#7c2d12", lineHeight: 1.7 }}
              >
                Para que tu pago quede registrado en el sistema:
                <br />
                <span
                  style={{ display: "block", marginTop: 6, paddingLeft: 4 }}
                >
                  1. Realiza la transferencia por{" "}
                  <strong>
                    {modalConfirmado.esEstudiante
                      ? "$3.000"
                      : "el valor de la cuota del mes"}
                  </strong>
                  .<br />
                  2. Envía el <strong>comprobante de pago</strong> por el{" "}
                  <strong>WhatsApp del grupo</strong>.<br />
                  3. La contadora lo registrará en el sistema.
                </span>
              </div>
            </div>

            <div
              style={{
                background: "#f0fdf4",
                border: "1px solid #bbf7d0",
                borderRadius: 12,
                padding: "10px 14px",
                marginBottom: 18,
                fontSize: 12,
                color: "#14532d",
                lineHeight: 1.6,
              }}
            >
              💬 <strong>¿Cuál es el WhatsApp del grupo?</strong> Es el mismo
              grupo de mensajería donde te coordinan los ensayos y misas.
            </div>

            <button
              onClick={() => setModalConfirmado(null)}
              style={{
                width: "100%",
                background: "linear-gradient(135deg,#1d6fc7,#1a4d8f)",
                border: "none",
                borderRadius: 12,
                padding: "12px 0",
                fontSize: 14,
                fontWeight: 700,
                color: "white",
                cursor: "pointer",
              }}
            >
              Entendido
            </button>
          </div>
        </div>
      )}

      {/* ── Modal: ¿eres estudiante? ── */}
      {modalTipo && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.40)",
            backdropFilter: "blur(4px)",
            WebkitBackdropFilter: "blur(4px)",
            zIndex: 9999,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              background: "rgba(255,255,255,0.97)",
              borderRadius: 22,
              padding: "28px 24px",
              maxWidth: 360,
              width: "90%",
              boxShadow: "0 24px 72px rgba(0,0,0,0.18)",
            }}
          >
            <div
              style={{ fontSize: 30, textAlign: "center", marginBottom: 10 }}
            >
              🎓
            </div>
            <div
              style={{
                fontSize: 16,
                fontWeight: 700,
                color: "#1c1c1e",
                textAlign: "center",
                marginBottom: 8,
              }}
            >
              ¿Cuál es tu situación?
            </div>
            <div
              style={{
                fontSize: 13,
                color: "#6a6a70",
                textAlign: "center",
                marginBottom: 20,
                lineHeight: 1.6,
              }}
            >
              Esto determina el valor de tu cuota mensual.
            </div>
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 10,
                marginBottom: 14,
              }}
            >
              <button
                onClick={() => inscribirmeCuota(false)}
                style={{
                  background: "linear-gradient(135deg,#1d6fc7,#1a4d8f)",
                  border: "none",
                  borderRadius: 14,
                  padding: "14px 16px",
                  cursor: "pointer",
                  textAlign: "left",
                }}
              >
                <div style={{ fontSize: 14, fontWeight: 700, color: "white" }}>
                  👤 Adulto
                </div>
                <div
                  style={{
                    fontSize: 12,
                    color: "rgba(255,255,255,0.8)",
                    marginTop: 3,
                  }}
                >
                  Pago el valor normal de la cuota
                </div>
              </button>
              <button
                onClick={() => inscribirmeCuota(true)}
                style={{
                  background: "white",
                  border: "1.5px solid #cfe0fb",
                  borderRadius: 14,
                  padding: "14px 16px",
                  cursor: "pointer",
                  textAlign: "left",
                }}
              >
                <div
                  style={{ fontSize: 14, fontWeight: 700, color: "#0a5ac8" }}
                >
                  🎓 Estudiante
                </div>
                <div style={{ fontSize: 12, color: "#6a6a70", marginTop: 3 }}>
                  Pago cuota rebajada de $3.000
                </div>
              </button>
            </div>
            <button
              onClick={() => setModalTipo(false)}
              style={{
                width: "100%",
                background: "transparent",
                border: "none",
                fontSize: 13,
                color: "#8a8a90",
                cursor: "pointer",
                padding: "6px 0",
              }}
            >
              Cancelar
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// Banner destacado del inicio (estilo afiche) — editable por admin, visible para todos
function BannerWidget({ isAdmin }) {
  const [url, setUrl] = useState("");
  const [meta, setMeta] = useState({
    etiqueta: "",
    titulo: "",
    fecha: "",
    hora: "",
    lugar: "",
  });
  const [editing, setEditing] = useState(false);
  const [subiendo, setSubiendo] = useState(false);
  const [cargado, setCargado] = useState(false);
  const [activo, setActivo] = useState(false);

  async function alternarActivo(v) {
    setActivo(v);
    try {
      await setConfig("banner_destacado_activo", v ? "1" : "0");
    } catch (e) {}
  }

  useEffect(() => {
    getConfig("banner_destacado_activo")
      .then((v) => setActivo(v === "1"))
      .catch(() => {});
    getConfig("banner_destacado_url")
      .then((v) => setUrl(v || ""))
      .catch(() => {});
    getConfig("banner_destacado_meta")
      .then((v) => {
        try {
          if (v) setMeta((m) => ({ ...m, ...JSON.parse(v) }));
        } catch {}
        setCargado(true);
      })
      .catch(() => setCargado(true));
  }, []);

  async function subirImagen(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setSubiendo(true);
    try {
      const ext = (file.name.split(".").pop() || "jpg").toLowerCase();
      const path = `banners/destacado_${Date.now()}.${ext}`;
      const res = await fetch(
        `${SUPABASE_URL}/storage/v1/object/publico/${path}`,
        {
          method: "POST",
          headers: {
            apikey: SUPABASE_SERVICE_KEY,
            Authorization: `Bearer ${SUPABASE_SERVICE_KEY}`,
            "Content-Type": file.type || "image/jpeg",
            "x-upsert": "true",
          },
          body: file,
        }
      );
      if (!res.ok) throw new Error("subida falló");
      setUrl(`${SUPABASE_URL}/storage/v1/object/public/publico/${path}`);
    } catch (er) {
      alert("No se pudo subir la imagen. Intenta de nuevo.");
    }
    setSubiendo(false);
    if (e.target) e.target.value = "";
  }

  async function guardar() {
    try {
      await setConfig("banner_destacado_url", url);
      await setConfig("banner_destacado_meta", JSON.stringify(meta));
      setEditing(false);
    } catch (e) {
      alert("Error al guardar.");
    }
  }

  async function quitar() {
    setUrl("");
    setMeta({ etiqueta: "", titulo: "", fecha: "", hora: "", lugar: "" });
    try {
      await setConfig("banner_destacado_url", "");
      await setConfig("banner_destacado_meta", "");
    } catch (e) {}
    setEditing(false);
  }

  if (!cargado) return null;
  // El banner está oculto hasta que el administrador lo active
  if (!activo) {
    if (!isAdmin) return null;
    return (
      <div
        style={{
          marginBottom: 12,
          display: "flex",
          alignItems: "center",
          gap: 10,
          fontSize: 12,
          color: "#64748b",
        }}
      >
        <span>🖼️ Banner destacado oculto para los integrantes.</span>
        <button
          onClick={() => alternarActivo(true)}
          style={{
            background: "#0a5ac8",
            color: "white",
            border: "none",
            borderRadius: 8,
            padding: "5px 12px",
            fontSize: 11.5,
            fontWeight: 700,
            cursor: "pointer",
          }}
        >
          Activar banner
        </button>
      </div>
    );
  }
  // Sin banner y sin ser admin → no mostrar nada
  if (!url && !isAdmin) return null;
  // Sin banner pero admin → invitación a crear
  if (!url && isAdmin && !editing) {
    return (
      <div
        onClick={() => setEditing(true)}
        style={{
          marginBottom: 16,
          border: "2px dashed #cbd5e1",
          borderRadius: 18,
          padding: "20px",
          textAlign: "center",
          cursor: "pointer",
          color: "#94a3b8",
          fontSize: 13,
          fontWeight: 600,
          background: "#f8fafc",
        }}
      >
        🖼️ Toca para agregar un banner destacado al inicio
      </div>
    );
  }

  const hasMeta = meta.titulo || meta.fecha || meta.hora || meta.lugar;

  return (
    <div style={{ marginBottom: 16 }}>
      {url && (
        <div className="mj-banner">
          <img
            className="mj-banner-img"
            src={url}
            alt={meta.titulo || "Banner"}
          />
          <div className="mj-banner-scrim" />
          <div className="mj-banner-topline" />
          <div className="mj-banner-body">
            {meta.etiqueta && (
              <div className="mj-banner-eyebrow">
                <div
                  style={{
                    width: 5,
                    height: 5,
                    borderRadius: "50%",
                    background: "#fff8ec",
                  }}
                />
                <span>{meta.etiqueta}</span>
              </div>
            )}
            {meta.titulo && (
              <div className="mj-banner-title">{meta.titulo}</div>
            )}
            {(meta.fecha || meta.hora || meta.lugar) && (
              <div className="mj-banner-meta">
                {meta.fecha && (
                  <div className="mj-banner-meta-item">
                    <span className="ico">📅</span>
                    <span className="txt">{meta.fecha}</span>
                  </div>
                )}
                {meta.hora && (
                  <div className="mj-banner-meta-item">
                    <span className="ico">🕐</span>
                    <span className="txt">{meta.hora}</span>
                  </div>
                )}
                {meta.lugar && (
                  <div className="mj-banner-meta-item">
                    <span className="ico">📍</span>
                    <span className="txt">{meta.lugar}</span>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
      {isAdmin &&
        (editing ? (
          <div
            style={{
              marginTop: 10,
              background: "#f8fafc",
              border: "1px solid #e2e8f0",
              borderRadius: 14,
              padding: 14,
            }}
          >
            <div
              style={{
                fontSize: 12,
                fontWeight: 700,
                color: "#475569",
                marginBottom: 10,
              }}
            >
              Banner destacado del inicio
            </div>
            <input
              type="file"
              accept="image/*"
              disabled={subiendo}
              onChange={subirImagen}
              style={{ fontSize: 13, marginBottom: 10, display: "block" }}
            />
            {subiendo && (
              <div style={{ fontSize: 12, color: "#64748b", marginBottom: 8 }}>
                Subiendo imagen…
              </div>
            )}
            {url && (
              <img
                src={url}
                alt="preview"
                style={{
                  width: "100%",
                  borderRadius: 10,
                  marginBottom: 10,
                  maxHeight: 160,
                  objectFit: "cover",
                }}
              />
            )}
            {[
              ["etiqueta", "Etiqueta (ej: Próxima Celebración)"],
              ["titulo", "Título (ej: Mes del Corazón de Jesús)"],
              ["fecha", "Fecha (ej: Jueves 16 de julio)"],
              ["hora", "Hora (ej: 17:00 Hrs)"],
              ["lugar", "Lugar (ej: Templo Votivo de Maipú)"],
            ].map(([campo, ph]) => (
              <input
                key={campo}
                value={meta[campo]}
                onChange={(e) =>
                  setMeta((m) => ({ ...m, [campo]: e.target.value }))
                }
                placeholder={ph}
                style={{
                  width: "100%",
                  fontSize: 13,
                  padding: "8px 10px",
                  borderRadius: 8,
                  border: "1px solid #e2e8f0",
                  boxSizing: "border-box",
                  marginBottom: 8,
                }}
              />
            ))}
            <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
              <button
                onClick={guardar}
                style={{
                  background: "#0a5ac8",
                  color: "white",
                  border: "none",
                  borderRadius: 9,
                  padding: "8px 16px",
                  fontSize: 12.5,
                  fontWeight: 700,
                  cursor: "pointer",
                }}
              >
                Guardar
              </button>
              <button
                onClick={quitar}
                style={{
                  background: "white",
                  color: "#ef4444",
                  border: "1px solid #fecaca",
                  borderRadius: 9,
                  padding: "8px 16px",
                  fontSize: 12.5,
                  fontWeight: 600,
                  cursor: "pointer",
                }}
              >
                Quitar banner
              </button>
              <button
                onClick={() => setEditing(false)}
                style={{
                  background: "white",
                  color: "#6a6a70",
                  border: "1px solid #e2e8f0",
                  borderRadius: 9,
                  padding: "8px 16px",
                  fontSize: 12.5,
                  cursor: "pointer",
                  marginLeft: "auto",
                }}
              >
                Cerrar
              </button>
            </div>
          </div>
        ) : (
          <button
            onClick={() => setEditing(true)}
            style={{
              marginTop: 6,
              fontSize: 11.5,
              fontWeight: 700,
              color: "#0a5ac8",
              background: "none",
              border: "none",
              cursor: "pointer",
            }}
          >
            ✏️ Editar banner
          </button>
        ))}
      {isAdmin && !editing && (
        <button
          onClick={() => alternarActivo(false)}
          style={{
            marginTop: 6,
            marginLeft: 12,
            fontSize: 11.5,
            fontWeight: 700,
            color: "#b45309",
            background: "none",
            border: "none",
            cursor: "pointer",
          }}
        >
          <IconoOjo size={14} off style={{ marginRight: 5 }} />Ocultar banner
        </button>
      )}
    </div>
  );
}

// Herramientas del coro (mismas del perfil invitado, pensadas para integrantes)
const HERRAMIENTAS_CORO = [
  { id: "pauta_misa", icon: "🎼", titulo: "Pauta de Misa", desc: "Canciones y orden de la próxima misa" },
  { id: "material_ensayo", icon: "🎤", titulo: "Material de ensayo", desc: "Cantos, letras y audios por voz" },
  { id: "cancionero_digital", icon: "📖", titulo: "Cancionero Digital", desc: "Todos los cantos con acordes transponibles" },
  { id: "cancioneros", icon: "📚", titulo: "Cancioneros", desc: "Descarga los cancioneros del coro" },
];

// ── Reproductor de audio de referencia dentro de la misma página ──────────
let _audioPauta = null;
let _audioPautaStop = null;
function urlAudioReproducible(url) {
  const id = driveFileId(url);
  return id
    ? `https://www.googleapis.com/drive/v3/files/${id}?alt=media&key=${GDRIVE_API_KEY}`
    : url;
}
function youtubeId(url) {
  const m = String(url || "").match(
    /(?:youtu\.be\/|youtube\.com\/(?:watch\?(?:.*&)?v=|embed\/|shorts\/|live\/))([A-Za-z0-9_-]{11})/
  );
  return m ? m[1] : null;
}
function BotonAudioPauta({ url, size = 26, bg = "#1e3a5f", fs = 10 }) {
  const [estado, setEstado] = useState("idle"); // idle | cargando | sonando
  const [visor, setVisor] = useState(false); // reproductor de Drive incrustado (plan B)
  const stopRef = useRef(null);
  useEffect(
    () => () => {
      if (_audioPautaStop === stopRef.current && _audioPauta) {
        _audioPauta.pause();
        _audioPauta = null;
        _audioPautaStop = null;
      }
    },
    []
  );
  function alternar() {
    if (visor) {
      setVisor(false);
      return;
    }
    // YouTube: se reproduce en el mini reproductor de la misma página
    if (youtubeId(url)) {
      if (_audioPauta) {
        _audioPauta.pause();
        if (_audioPautaStop) _audioPautaStop();
      }
      setVisor(true);
      return;
    }
    if (estado !== "idle") {
      if (_audioPauta) _audioPauta.pause();
      _audioPauta = null;
      _audioPautaStop = null;
      setEstado("idle");
      return;
    }
    if (_audioPauta) {
      _audioPauta.pause();
      if (_audioPautaStop) _audioPautaStop();
    }
    const audio = new Audio(urlAudioReproducible(url));
    const parar = () => setEstado("idle");
    stopRef.current = parar;
    _audioPauta = audio;
    _audioPautaStop = parar;
    setEstado("cargando");
    audio.addEventListener("playing", () => setEstado("sonando"));
    audio.addEventListener("ended", parar);
    audio.addEventListener("error", () => {
      parar();
      _audioPauta = null;
      _audioPautaStop = null;
      // Plan B: reproductor de Drive incrustado en esta misma página (sin abrir otra ventana)
      if (driveFileId(url)) setVisor(true);
      else {
        alert("No se pudo reproducir este audio aquí. Se abrirá en otra pestaña.");
        window.open(url, "_blank", "noopener");
      }
    });
    audio.play().catch(() => {});
  }
  return (
    <>
    {visor && createPortal(
      <div style={{ position: "fixed", right: 16, bottom: typeof window !== "undefined" && window.innerWidth <= 768 ? "calc(84px + env(safe-area-inset-bottom, 0px))" : 16, zIndex: 5000, width: 340, maxWidth: "calc(100vw - 32px)", background: "#fff", borderRadius: 14, boxShadow: "0 12px 40px rgba(15,39,68,.3)", border: "1px solid #dbe4f0", overflow: "hidden" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 12px", background: "#1e3a5f", color: "#fff", fontSize: 12, fontWeight: 700 }}>
          <span>🎧 Audio de referencia</span>
          <button onClick={() => setVisor(false)} style={{ background: "none", border: "none", color: "#fff", fontSize: 15, cursor: "pointer" }}>✕</button>
        </div>
        {youtubeId(url) ? (
          <iframe title="Audio" src={`https://www.youtube.com/embed/${youtubeId(url)}?autoplay=1&rel=0`} allow="autoplay; encrypted-media" allowFullScreen style={{ width: "100%", height: 190, border: 0, display: "block" }} />
        ) : (
          <iframe title="Audio" src={`https://drive.google.com/file/d/${driveFileId(url)}/preview`} allow="autoplay" style={{ width: "100%", height: 150, border: 0, display: "block" }} />
        )}
      </div>,
      document.body
    )}
    <button
      onClick={alternar}
      title={estado === "idle" ? "Escuchar audio de referencia" : "Pausar"}
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        width: size,
        height: size,
        borderRadius: "50%",
        background: bg,
        color: "#fff",
        fontSize: fs,
        border: "none",
        cursor: "pointer",
        boxShadow: "0 1px 3px rgba(0,0,0,0.18)",
      }}
    >
      {estado === "cargando" ? "…" : estado === "sonando" ? "⏸" : "▶"}
    </button>
    </>
  );
}

// ── Acceso por pauta: config "pauta_acceso_<id>" = {restringida, ids[]} ──
async function mjCargarAccesosPauta() {
  const url = `${SUPABASE_URL}/rest/v1/config?select=key,value&key=like.${encodeURIComponent("pauta_acceso_")}*`;
  const tokens = [_authToken, SUPABASE_KEY, SUPABASE_SERVICE_KEY].filter((v, i, ar) => v && ar.indexOf(v) === i);
  for (const t of tokens) {
    try {
      const r = await fetch(url, { headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${t}` } });
      if (!r.ok) continue;
      const rows = await r.json();
      const mapa = {};
      (Array.isArray(rows) ? rows : []).forEach((x) => {
        try {
          mapa[x.key.slice("pauta_acceso_".length)] = typeof x.value === "string" ? JSON.parse(x.value) : x.value;
        } catch (e) {}
      });
      return mapa;
    } catch (e) {}
  }
  return {};
}
function mjFiltrarPautasPorAcceso(pautas, accesos, user) {
  if (!user || user.cuerda === "Admin") return pautas;
  return (pautas || []).filter((p) => {
    const ac = accesos && accesos[p.id];
    if (!ac || !ac.restringida) return true;
    return (ac.ids || []).map(String).includes(String(user.id));
  });
}
