const NOTAS_CROMATICAS = [
  "C",
  "C#",
  "D",
  "D#",
  "E",
  "F",
  "F#",
  "G",
  "G#",
  "A",
  "A#",
  "B",
];

// Nombres en formato latinoamericano (Do, Re, Mi...)
const NOTA_LATINA = {
  C: "Do",
  "C#": "Do#",
  D: "Re",
  "D#": "Re#",
  E: "Mi",
  F: "Fa",
  "F#": "Fa#",
  G: "Sol",
  "G#": "Sol#",
  A: "La",
  "A#": "La#",
  B: "Si",
};
function notaLatina(nota) {
  return NOTA_LATINA[nota] || nota;
}

// Google Drive Picker (OAuth client-only, sin secreto)
// ID de la carpeta pública de Google Drive con los PDFs del cancionero
const GDRIVE_FOLDER_ID = "18AqJFgonJlvXh-CxZuKRQC2oXLVK2BjF";
const GDRIVE_API_KEY = "AIzaSyAHncVhw60TS60FQIvwUwfGkLsJEO4XTuE";

// Lista todos los PDFs de la carpeta pública sin OAuth
async function listarPDFsDrive(busqueda = "") {
  let q = `'${GDRIVE_FOLDER_ID}' in parents and mimeType='application/pdf' and trashed=false`;
  if (busqueda.trim())
    q += ` and name contains '${busqueda.trim().replace(/'/g, "\\'")}'`;
  const url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(
    q
  )}&key=${GDRIVE_API_KEY}&fields=files(id,name)&orderBy=name&pageSize=200`;
  const res = await fetch(url);
  if (!res.ok) throw new Error("No se pudo acceder a la carpeta de Drive");
  const data = await res.json();
  return (data.files || []).map((f) => ({
    id: f.id,
    nombre: f.name.replace(/\.pdf$/i, ""),
    url: `https://drive.google.com/file/d/${f.id}/view`,
  }));
}

// Lista TODOS los PDFs sin filtro (para el directorio completo)
async function listarTodosDrive() {
  let allFiles = [];
  let pageToken = null;
  do {
    const q = `'${GDRIVE_FOLDER_ID}' in parents and mimeType='application/pdf' and trashed=false`;
    let url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(
      q
    )}&key=${GDRIVE_API_KEY}&fields=files(id,name),nextPageToken&orderBy=name&pageSize=200`;
    if (pageToken) url += `&pageToken=${pageToken}`;
    const res = await fetch(url);
    if (!res.ok) break;
    const data = await res.json();
    allFiles = allFiles.concat(data.files || []);
    pageToken = data.nextPageToken || null;
  } while (pageToken);
  return allFiles.map((f) => ({
    id: f.id,
    nombre: f.name.replace(/\.pdf$/i, ""),
    url: `https://drive.google.com/file/d/${f.id}/view`,
  }));
}

function transponerAcorde(acorde, semis) {
  if (!acorde || semis === 0) return acorde;
  const flatMap = {
    Db: "C#",
    Eb: "D#",
    Fb: "E",
    Gb: "F#",
    Ab: "G#",
    Bb: "A#",
    Cb: "B",
  };
  const regex = /^([A-G][#b]?)(.*)/;
  const m = acorde.match(regex);
  if (!m) return acorde;
  const rawNote = m[1];
  const suffix = m[2];
  const normalizado = flatMap[rawNote] || rawNote;
  const idx = NOTAS_CROMATICAS.indexOf(normalizado);
  if (idx === -1) return acorde;
  const newIdx = (((idx + semis) % 12) + 12) % 12;
  return NOTAS_CROMATICAS[newIdx] + suffix;
}

// ── Transposición de acordes LATINOS (Do, Re, Mim, Lam, Si7, Fa#...) ──
// Cadena cromática en latino, preservando mayúscula/minúscula inicial
const LATIN_CROMATICA = [
  "Do",
  "Do#",
  "Re",
  "Re#",
  "Mi",
  "Fa",
  "Fa#",
  "Sol",
  "Sol#",
  "La",
  "La#",
  "Si",
];
// Regex que captura nota latina (raíz) + sufijo (m, 7, sus, etc.)
const LATIN_NOTA_RE = /^(Do#|Re#|Fa#|Sol#|La#|Do|Re|Mi|Fa|Sol|La|Si)(.*)$/i;

function esAcordeLatino(token) {
  const t = token.trim();
  if (!t) return false;
  // Quitar paréntesis tipo (Final: La) no son acordes sueltos
  const m = t.match(LATIN_NOTA_RE);
  if (!m) return false;
  // El sufijo debe ser solo sufijos de acorde válidos (m, 7, maj, sus, dim, aug, add, #, b, números, /)
  const suffix = m[2];
  return /^(m|maj|min|dim|aug|sus|add|M|°|\+)?[#b]?\d*(\/(Do#|Re#|Fa#|Sol#|La#|Do|Re|Mi|Fa|Sol|La|Si)[#b]?)?$/i.test(
    suffix
  );
}

function transponerAcordeLatino(acorde, semis) {
  if (!acorde || semis === 0) return acorde;
  const m = acorde.match(LATIN_NOTA_RE);
  if (!m) return acorde;
  const raiz = m[1];
  const suffix = m[2];
  // Normalizar a forma canónica para buscar índice
  const raizCanonica =
    raiz.charAt(0).toUpperCase() + raiz.slice(1).toLowerCase();
  const idx = LATIN_CROMATICA.findIndex(
    (n) => n.toLowerCase() === raizCanonica.toLowerCase()
  );
  if (idx === -1) return acorde;
  const newIdx = (((idx + semis) % 12) + 12) % 12;
  let nueva = LATIN_CROMATICA[newIdx];
  // Preservar si la raíz original era minúscula (convención: menor)
  if (raiz[0] === raiz[0].toLowerCase())
    nueva = nueva.charAt(0).toLowerCase() + nueva.slice(1);
  // Manejar el caso de acorde con bajo (slash): transponer también el bajo
  let suffixFinal = suffix;
  const slashM = suffix.match(
    /^(.*)\/(Do#|Re#|Fa#|Sol#|La#|Do|Re|Mi|Fa|Sol|La|Si)([#b]?)$/i
  );
  if (slashM) {
    const bajoIdx = LATIN_CROMATICA.findIndex(
      (n) =>
        n.toLowerCase() ===
        (
          slashM[2].charAt(0).toUpperCase() + slashM[2].slice(1).toLowerCase()
        ).toLowerCase()
    );
    if (bajoIdx !== -1) {
      const nuevoBajo = LATIN_CROMATICA[(((bajoIdx + semis) % 12) + 12) % 12];
      suffixFinal = slashM[1] + "/" + nuevoBajo;
    }
  }
  return nueva + suffixFinal;
}

function transponerLineaLatina(linea, semis) {
  if (semis === 0) return linea;
  // Tokenizar preservando espacios para mantener alineación
  return linea.replace(/(\S+)/g, (tok) =>
    esAcordeLatino(tok) ? transponerAcordeLatino(tok, semis) : tok
  );
}

function transponerLineaInteligente(linea, semis) {
  if (semis === 0) return linea;
  const tokens = linea.trim().split(/\s+/).filter(Boolean);
  if (!tokens.length) return linea;
  const latinos = tokens.filter(esAcordeLatino).length;
  // Si la mayoría de tokens son acordes latinos → es línea de acordes latinos
  if (latinos / tokens.length >= 0.5)
    return transponerLineaLatina(linea, semis);
  // Si no, intentar como americano
  return transponerLinea(linea, semis);
}

function transponerLinea(linea, semis) {
  // Detecta si la línea es de acordes: >= 50% de tokens son acordes
  if (semis === 0) return linea;
  const tokens = linea.trim().split(/\s+/);
  if (tokens.length === 0) return linea;
  const acordeRe = /^[A-G][#b]?(m|maj|min|dim|aug|sus|add)?\d*(\/[A-G][#b]?)?$/;
  const contAcordes = tokens.filter((t) => acordeRe.test(t)).length;
  if (contAcordes / tokens.length < 0.5) return linea;
  return tokens
    .map((t) => (acordeRe.test(t) ? transponerAcorde(t, semis) : t))
    .join(" ");
}

function transponerTextoCompleto(texto, semis) {
  if (!texto || semis === 0) return texto;
  return texto
    .split("\n")
    .map((l) => transponerLineaInteligente(l, semis))
    .join("\n");
}

function drivePreviewUrl(url) {
  if (!url) return "";
  // Si es de Google Drive: convertir a /preview (su visor no muestra descarga si el archivo lo restringe)
  if (/drive\.google\.com/i.test(url)) {
    return url
      .replace(/\/view(\?.*)?$/, "/preview")
      .replace(/\/edit(\?.*)?$/, "/preview");
  }
  // Si es un PDF directo (ej: Supabase): ocultar la barra del visor del navegador (descarga/imprimir)
  if (/\.pdf(\?|$)/i.test(url)) {
    const limpia = url.split("#")[0];
    return `${limpia}#toolbar=0&navpanes=0`;
  }
  return url;
}

// ── Componente QR pequeño usando api.qrserver.com (gratis, sin clave) ──
function QRImg({ data, size = 120, borderColor = "#1a3a2a" }) {
  if (!data) return null;
  const src = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(
    data
  )}&color=1a3a2a&bgcolor=ffffff&margin=8`;
  return (
    <div
      style={{
        background: "white",
        borderRadius: 12,
        padding: 6,
        border: `2px solid ${borderColor}`,
        boxShadow: "0 2px 8px rgba(0,0,0,0.12)",
        display: "inline-block",
      }}
    >
      <img
        src={src}
        alt="QR"
        width={size}
        height={size}
        style={{ display: "block", borderRadius: 4 }}
      />
    </div>
  );
}

