// ── LetraRenderer acepta formatoLatino para mostrar acordes en Do/Re/Mi ──
// Renderiza una línea de acordes en monospace, coloreada y convertida a latino,
// preservando las posiciones exactas (espacios) de la línea original
function LineaAcordesMono({ linea, color }) {
  // Recorre la línea respetando espacios; convierte cada token-acorde a latino
  const re = /(\s+)|(\S+)/g;
  const partes = [];
  let m,
    idx = 0;
  while ((m = re.exec(linea)) !== null) {
    if (m[1]) partes.push({ tipo: "espacio", val: m[1], k: idx++ });
    else partes.push({ tipo: "tok", val: m[2], k: idx++ });
  }
  return (
    <div
      style={{
        fontFamily: "'Courier New', monospace",
        fontSize: 13,
        lineHeight: 1.4,
        whiteSpace: "pre",
        color: "#222",
        fontWeight: 700,
      }}
    >
      {partes.map((p) => {
        if (p.tipo === "espacio") return <span key={p.k}>{p.val}</span>;
        const esAc = ACORDE_RE.test(p.val) || esAcordeLatino(p.val);
        if (!esAc) return <span key={p.k}>{p.val}</span>;
        const latino = aLatino(p.val);
        const american = latinoAAmericano(p.val);
        // El ancho debe coincidir con el original para no desalinear: si el latino es más largo, igual respetamos
        return (
          <AcordeConDiagrama
            key={p.k}
            acorde={latino}
            acordeAmerican={american}
            colorAcorde={color}
          />
        );
      })}
    </div>
  );
}

function LetraRenderer({
  texto,
  semis = 0,
  colorAcorde,
  formatoLatino = false,
}) {
  // Si es el formato JSON nuevo (con posiciones X reales), usar el renderer posicional
  if (typeof texto === "string" && texto.startsWith("JSON_PDF::")) {
    return (
      <LetraRendererPosicional
        json={texto.slice("JSON_PDF::".length)}
        semis={semis}
        colorAcorde={colorAcorde}
      />
    );
  }
  // Texto plano (formato antiguo) — aplicar transposición y renderer monospace
  const textoT = transponerTextoCompleto(texto, semis);
  const bloques = parsearLetra(textoT);
  if (!bloques.length)
    return (
      <span style={{ color: "#aaa", fontStyle: "italic" }}>
        Sin letra cargada aún.
      </span>
    );

  return (
    <div
      style={{
        fontFamily: "'Courier New', monospace",
        fontSize: 13,
        lineHeight: 1.5,
        color: "#222",
      }}
    >
      {bloques.map((b, i) => {
        if (b.tipo === "vacio") return <div key={i} style={{ height: 10 }} />;
        if (b.tipo === "seccion")
          return (
            <div
              key={i}
              style={{
                fontFamily: "'Segoe UI', Arial, sans-serif",
                fontSize: 11,
                fontWeight: 800,
                color: colorAcorde || "#1a6fb5",
                textTransform: "uppercase",
                letterSpacing: 1.5,
                marginTop: 16,
                marginBottom: 4,
                background: (colorAcorde || "#1a6fb5") + "15",
                display: "inline-block",
                padding: "2px 8px",
                borderRadius: 7,
              }}
            >
              {b.texto}
            </div>
          );
        if (b.tipo === "par")
          return (
            <div key={i} style={{ marginBottom: 2 }}>
              <LineaAcordesMono
                linea={b.acordes}
                color={colorAcorde || "#1a6fb5"}
              />
              <div style={{ whiteSpace: "pre", lineHeight: 1.5 }}>
                {b.letra}
              </div>
            </div>
          );
        if (b.tipo === "soloAcordes")
          return (
            <LineaAcordesMono
              key={i}
              linea={b.acordes}
              color={colorAcorde || "#1a6fb5"}
            />
          );
        if (b.tipo === "letra")
          return (
            <div key={i} style={{ whiteSpace: "pre", lineHeight: 1.5 }}>
              {b.texto}
            </div>
          );
        return null;
      })}
    </div>
  );
}

// Renderer que posiciona acordes ABSOLUTAMENTE sobre la letra usando coordenadas X del PDF
// Esto respeta exactamente la alineación original sin depender de contar espacios
function LetraRendererPosicional({ json, semis, colorAcorde }) {
  let lineas;
  try {
    lineas = JSON.parse(json);
  } catch {
    return <span style={{ color: "#aaa" }}>No se pudo leer la letra.</span>;
  }
  if (!lineas || !lineas.length)
    return (
      <span style={{ color: "#aaa", fontStyle: "italic" }}>Sin letra.</span>
    );

  // Factor de escala: convertir unidades X del PDF (puntos) a px en pantalla
  const ESCALA = 1.0; // 1 punto PDF ≈ 1 px (ajustable)
  const COLOR = colorAcorde || "#1a6fb5";

  function textoDeLinea(items) {
    return items
      .map((it) => it.str)
      .join("")
      .trim();
  }
  function esSeccion(txt) {
    return /^(CORO|ESTROFA|ESTROFAS|PUENTE|INTRO|OUTRO|BRIDGE|VERSO|PRE-CORO|FINAL|SALMO|RESPONSORIO)/i.test(
      txt
    );
  }

  return (
    <div
      style={{
        fontFamily: "'Segoe UI', Arial, sans-serif",
        fontSize: 14,
        color: "#222",
      }}
    >
      {lineas.map((linea, i) => {
        if (linea.salto || !linea.items.length)
          return <div key={i} style={{ height: 8 }} />;
        const txt = textoDeLinea(linea.items);
        // Sección
        if (esSeccion(txt) && linea.items.length <= 3) {
          return (
            <div
              key={i}
              style={{
                fontSize: 11,
                fontWeight: 800,
                color: COLOR,
                textTransform: "uppercase",
                letterSpacing: 1.2,
                marginTop: 14,
                marginBottom: 2,
                background: COLOR + "15",
                display: "inline-block",
                padding: "2px 8px",
                borderRadius: 7,
              }}
            >
              {txt}
            </div>
          );
        }
        // ¿Es línea de acordes?
        if (lineaEsAcordes(linea.items)) {
          // Posicionar cada acorde de forma absoluta según su X
          const maxX = Math.max(...linea.items.map((it) => it.x), 0);
          return (
            <div
              key={i}
              style={{
                position: "relative",
                height: 20,
                minWidth: maxX * ESCALA + 60 + "px",
              }}
            >
              {linea.items.map((it, j) => {
                const tok = it.str.trim();
                if (!tok) return null;
                const esAc = ACORDE_RE.test(tok) || esAcordeLatino(tok);
                const tokTranspuesto =
                  esAc && semis
                    ? esAcordeLatino(tok)
                      ? transponerAcordeLatino(tok, semis)
                      : transponerAcorde(tok, semis)
                    : tok;
                const mostrar = esAc ? aLatino(tokTranspuesto) : tok;
                const american = esAc
                  ? latinoAAmericano(aLatino(tokTranspuesto))
                  : null;
                return (
                  <span
                    key={j}
                    style={{
                      position: "absolute",
                      left: it.x * ESCALA + "px",
                      top: 0,
                      fontSize: 12.5,
                      fontWeight: 700,
                      color: esAc ? COLOR : "#222",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {esAc ? (
                      <AcordeConDiagrama
                        acorde={mostrar}
                        acordeAmerican={american}
                        colorAcorde={COLOR}
                      />
                    ) : (
                      mostrar
                    )}
                  </span>
                );
              })}
            </div>
          );
        }
        // Línea de letra normal — posicionar también por X para mantener sangría
        const primerX = linea.items[0]?.x || 0;
        return (
          <div
            key={i}
            style={{
              marginLeft: primerX * ESCALA + "px",
              lineHeight: 1.5,
              whiteSpace: "pre-wrap",
            }}
          >
            {txt}
          </div>
        );
      })}
    </div>
  );
}

