function CancioneroPautaCard({ pauta, canciones, isAdmin, onAbrir, onReload }) {
  const asigs = (() => {
    try {
      return typeof pauta.asignaciones === "string"
        ? JSON.parse(pauta.asignaciones)
        : pauta.asignaciones || [];
    } catch {
      return [];
    }
  })();
  const fecha = pauta.fecha
    ? new Date(pauta.fecha + "T00:00:00").toLocaleDateString("es-CL", {
        weekday: "long",
        day: "numeric",
        month: "long",
        year: "numeric",
      })
    : "";

  async function eliminar() {
    if (!confirm(`¿Eliminar la pauta "${pauta.titulo}"?`)) return;
    try {
      await deleteRecord("cancionero_pautas", pauta.id);
      onReload();
    } catch (e) {
      alert("Error: " + e.message);
    }
  }

  return (
    <Card hover style={{ padding: 16 }}>
      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          gap: 10,
          marginBottom: 12,
        }}
      >
        <div
          style={{
            width: 44,
            height: 44,
            borderRadius: 12,
            background: C.primaryLight,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 22,
            flexShrink: 0,
          }}
        >
          🎼
        </div>
        <div style={{ flex: 1 }}>
          <div
            style={{
              fontSize: 14,
              fontWeight: 700,
              color: C.dark,
              lineHeight: 1.3,
            }}
          >
            {pauta.titulo}
          </div>
          {fecha && (
            <div
              style={{
                fontSize: 11,
                color: C.gray,
                marginTop: 2,
                textTransform: "capitalize",
              }}
            >
              {fecha}
            </div>
          )}
          {pauta.comunidad && (
            <div
              style={{
                fontSize: 11,
                color: C.primary,
                fontWeight: 500,
                marginTop: 2,
              }}
            >
              ⛪ {pauta.comunidad}
            </div>
          )}
        </div>
      </div>
      <div
        style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 12 }}
      >
        {asigs.slice(0, 5).map((a, i) => {
          const mom = MOMENTOS_LITURGICOS.find((m) => m.id === a.momento);
          return mom ? (
            <span
              key={i}
              style={{
                fontSize: 10,
                padding: "2px 7px",
                borderRadius: 12,
                background: mom.color + "18",
                color: mom.color,
                fontWeight: 600,
              }}
            >
              {mom.icon}
            </span>
          ) : null;
        })}
        {asigs.length > 5 && (
          <span style={{ fontSize: 10, color: C.gray }}>
            +{asigs.length - 5}
          </span>
        )}
      </div>
      <div style={{ display: "flex", gap: 6 }}>
        <button
          onClick={() => onAbrir(pauta)}
          style={{
            flex: 1,
            padding: "7px 0",
            borderRadius: 10,
            border: "none",
            background: C.primary,
            color: "white",
            fontSize: 12,
            fontWeight: 600,
            cursor: "pointer",
          }}
        >
          📋 Ver pauta
        </button>
        {isAdmin && (
          <button
            onClick={eliminar}
            style={{
              padding: "7px 10px",
              borderRadius: 10,
              border: "none",
              background: "#fee2e2",
              color: C.danger,
              fontSize: 12,
              cursor: "pointer",
            }}
          >
            🗑
          </button>
        )}
      </div>
    </Card>
  );
}

