// Renderiza notas con **negrita** y saltos de línea
function renderNotas(texto) {
  if (!texto) return null;
  const lineas = String(texto).split("\n");
  return lineas.map((linea, li) => {
    // **negrita**: se alterna con cada "**"; asteriscos sobrantes o vacíos no se muestran
    const partes = linea.split("**");
    return (
      <span key={li}>
        {partes.map((p, pi) =>
          p === "" ? null : pi % 2 === 1 ? (
            <strong key={pi} style={{ fontWeight: 700 }}>
              {p}
            </strong>
          ) : (
            <span key={pi}>{p}</span>
          )
        )}
        {li < lineas.length - 1 && <br />}
      </span>
    );
  });
}

// Editor de notas: textarea con barra de formato (negrita + saltos de línea)
function NotasEditor({ value, onChange, placeholder }) {
  const ref = useRef(null);

  const wrapBold = () => {
    const ta = ref.current;
    if (!ta) return;
    const start = ta.selectionStart,
      end = ta.selectionEnd;
    const sel = value.slice(start, end);
    const nuevo = sel
      ? value.slice(0, start) + "**" + sel + "**" + value.slice(end)
      : value.slice(0, start) + "**texto**" + value.slice(end);
    onChange(nuevo);
    setTimeout(() => {
      ta.focus();
      if (sel) {
        ta.selectionStart = start + 2;
        ta.selectionEnd = end + 2;
      } else {
        ta.selectionStart = start + 2;
        ta.selectionEnd = start + 7;
      }
    }, 0);
  };

  const insertBullet = () => {
    const ta = ref.current;
    if (!ta) return;
    const start = ta.selectionStart;
    const antes = value.slice(0, start);
    const prefijo = antes === "" || antes.endsWith("\n") ? "• " : "\n• ";
    const nuevo = antes + prefijo + value.slice(start);
    onChange(nuevo);
    setTimeout(() => {
      ta.focus();
      ta.selectionStart = ta.selectionEnd = start + prefijo.length;
    }, 0);
  };

  return (
    <div
      style={{
        border: `1px solid ${C.border}`,
        borderRadius: 12,
        overflow: "hidden",
        background: "white",
      }}
    >
      {/* Barra de formato */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 4,
          padding: "6px 8px",
          borderBottom: `1px solid ${C.border}`,
          background: "rgba(0,0,0,0.015)",
        }}
      >
        <button
          type="button"
          onClick={wrapBold}
          title="Negrita (selecciona texto y pulsa)"
          style={{
            width: 30,
            height: 28,
            borderRadius: 7,
            border: "1px solid rgba(60,60,67,0.10)",
            background: "white",
            cursor: "pointer",
            fontWeight: 800,
            fontSize: 13,
            color: C.dark,
          }}
        >
          B
        </button>
        <button
          type="button"
          onClick={insertBullet}
          title="Agregar viñeta"
          style={{
            width: 30,
            height: 28,
            borderRadius: 7,
            border: "1px solid rgba(60,60,67,0.10)",
            background: "white",
            cursor: "pointer",
            fontSize: 14,
            color: C.dark,
          }}
        >
          •
        </button>
        <span
          style={{
            marginLeft: "auto",
            fontSize: 10.5,
            color: C.gray,
            paddingRight: 4,
          }}
        >
          Enter = salto de línea · <strong>**texto**</strong> = negrita
        </span>
      </div>
      <textarea
        ref={ref}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        rows={6}
        style={{
          width: "100%",
          border: "none",
          outline: "none",
          resize: "vertical",
          padding: "11px 13px",
          fontSize: 13,
          lineHeight: 1.6,
          color: C.dark,
          boxSizing: "border-box",
          background: "white",
          minHeight: 120,
          fontFamily: "inherit",
        }}
      />
      {/* Vista previa */}
      {value && value.trim() && (
        <div
          style={{
            borderTop: `1px solid ${C.border}`,
            padding: "10px 13px",
            background: "rgba(0,0,0,0.015)",
          }}
        >
          <div
            style={{
              fontSize: 9.5,
              fontWeight: 700,
              color: C.gray,
              letterSpacing: "0.06em",
              textTransform: "uppercase",
              marginBottom: 5,
            }}
          >
            Vista previa
          </div>
          <div style={{ fontSize: 12.5, color: C.dark, lineHeight: 1.6 }}>
            {renderNotas(value)}
          </div>
        </div>
      )}
    </div>
  );
}

