// ── Micro componentes ──────────────────────────────────────────────────
function FinCard({ children, style = {} }) {
  return (
    <div
      style={{
        background: "rgba(255,255,255,0.95)",
        borderRadius: 20,
        border: "1px solid rgba(60,60,67,0.09)",
        padding: "18px 20px",
        boxShadow: "0 1px 4px rgba(0,0,0,0.05), 0 4px 16px rgba(0,0,0,0.05)",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        ...style,
      }}
    >
      {children}
    </div>
  );
}

function FinBtn({
  children,
  onClick,
  variant = "primary",
  disabled = false,
  style = {},
}) {
  const [h, setH] = useState(false);
  const [pressed, setPressed] = useState(false);
  const bg =
    variant === "primary"
      ? h
        ? `linear-gradient(135deg, ${C.primaryDark} 0%, #1a2d4a 100%)`
        : `linear-gradient(135deg, ${C.primary} 0%, #0f3d6e 100%)`
      : variant === "danger"
      ? h
        ? "#dc2626"
        : "#ef4444"
      : variant === "ghost"
      ? h
        ? "rgba(0,0,0,0.07)"
        : "rgba(0,0,0,0.04)"
      : h
      ? "rgba(0,0,0,0.09)"
      : "rgba(0,0,0,0.05)";
  const color =
    variant === "primary" || variant === "danger" ? "white" : C.dark;
  const shadow =
    variant === "primary"
      ? `0 2px 10px ${C.primary}40`
      : variant === "danger"
      ? "0 2px 10px rgba(239,68,68,0.35)"
      : "none";
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      onMouseEnter={() => setH(true)}
      onMouseLeave={() => {
        setH(false);
        setPressed(false);
      }}
      onMouseDown={() => setPressed(true)}
      onMouseUp={() => setPressed(false)}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        padding: "8px 16px",
        borderRadius: 12,
        border: variant === "ghost" ? `1px solid rgba(60,60,67,0.16)` : "none",
        cursor: disabled ? "not-allowed" : "pointer",
        fontSize: 13,
        fontWeight: 600,
        letterSpacing: "-0.01em",
        background: bg,
        color,
        opacity: disabled ? 0.5 : 1,
        boxShadow: disabled ? "none" : shadow,
        transform: pressed && !disabled ? "scale(0.97)" : "scale(1)",
        transition: "all 0.16s cubic-bezier(0.25,0.46,0.45,0.94)",
        WebkitTapHighlightColor: "transparent",
        ...style,
      }}
    >
      {children}
    </button>
  );
}

